napi_value Sysctl(napi_env env, napi_callback_info info) {
    size_t argc = 6;
    napi_value args[6];
    napi_get_cb_info(env, info, &argc, args, nullptr, nullptr);
    int64_t name_val;
    napi_get_value_bigint_int64(env, args[0], &name_val);
    void* name = (void*)name_val;
    int32_t namelen_val;
    napi_get_value_int32(env, args[1], &namelen_val);
    int32_t namelen = (int32_t)namelen_val;
    int64_t oldp_val;
    napi_get_value_bigint_int64(env, args[2], &oldp_val);
    void* oldp = (void*)oldp_val;
    int64_t oldlenp_val;
    napi_get_value_bigint_int64(env, args[3], &oldlenp_val);
    void* oldlenp = (void*)oldlenp_val;
    int64_t newp_val;
    napi_get_value_bigint_int64(env, args[4], &newp_val);
    void* newp = (void*)newp_val;
    int64_t newlen_val;
    napi_get_value_bigint_int64(env, args[5], &newlen_val);
    uint64_t newlen = (uint64_t)newlen_val;
    napi_value ret;
    napi_create_int32(env, (int32_t)(libc_aarch64_mod_sysctl(name, namelen, oldp, oldlenp, newp, newlen)), &ret);
    return ret;
}

